
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_p86vwn_ft_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_p86vwn_ft", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-7.022698722610340e-02, -6.924075493484312e-02, -6.782919545818521e-02, -6.581350301246615e-02, -6.294530204664819e-02, -5.888803654387965e-02, -5.321118002993365e-02, -4.544924445837978e-02, -3.539406246300547e-02, -2.388619788805122e-02, -1.437168407286880e-02, -4.147066780465897e-02, -4.817363689838272e-02, -3.529953637587478e-02, -1.874342751439442e-02, -1.132289122287316e-03, 5.591700151056423e-03, -5.794646212868196e-03, -2.285847295299384e-03, -3.201027765312986e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


